<template><section class="panel"><div class="panel-heading"><div><h2>{{ title }}</h2><p>{{ description }}</p></div><button class="primary" type="button" @click="openNew">Tambah</button></div><div v-if="loading" class="state">Memuat…</div><div v-else-if="!items.length" class="state">Belum ada data. Tambahkan konten pertama.</div><div v-else class="items"><article v-for="item in items" :key="item.id" class="item"><div><strong>{{ item.title || item.question || item.label || item.key }}</strong><p>{{ item.description || item.answer || item.value }}</p><small>{{ item.is_active === false ? 'Tidak dipublikasikan' : 'Dipublikasikan' }}</small></div><div class="actions"><button type="button" @click="edit(item)">Edit</button><button type="button" class="danger" @click="remove(item)">Hapus</button></div></article></div><AppModal v-model="open" :title="editing ? 'Edit ' + title : 'Tambah ' + title" :loading="saving" @confirm="save"><div class="form-grid"><label v-if="type === 'gallery'">Judul<input v-model="form.title"></label><label v-if="type === 'progress' || type === 'faq'">{{ type === 'faq' ? 'Pertanyaan' : 'Judul' }}<input v-model="form.title"></label><label v-if="type === 'contact'">Label<input v-model="form.label"></label><label v-if="type === 'contact'">Kunci<input v-model="form.key"></label><label v-if="type === 'gallery'">Kategori<input v-model="form.category"></label><label v-if="type === 'progress'">Tanggal update<input v-model="form.progress_date" type="date"></label><label v-if="type === 'progress'">Persentase<input v-model.number="form.percentage" type="number" min="0" max="100"></label><label class="wide">{{ type === 'faq' ? 'Jawaban' : type === 'contact' ? 'Nilai' : 'Deskripsi' }}<textarea v-model="form.description" rows="4"></textarea></label><label v-if="type === 'gallery' || type === 'progress'">Foto<input type="file" accept="image/jpeg,image/png,image/webp" @change="selectFile"></label><label v-if="type !== 'contact'">Urutan<input v-model.number="form.sort_order" type="number" min="0"></label><label class="check"><input v-model="form.is_active" type="checkbox"> Tampilkan di website publik</label></div></AppModal></section></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import AppModal from '@/components/ui/AppModal.vue'; import { galleryService } from '@/services/galleryService'; import { progressService } from '@/services/progressService'; import { faqService } from '@/services/faqService'; import { contactService } from '@/services/contactService'
const props = defineProps<{ type: 'gallery'|'progress'|'faq'|'contact' }>(); const emit = defineEmits<{ notify: [message: string, type?: string] }>(); const items = ref<any[]>([]); const loading = ref(true); const saving = ref(false); const open = ref(false); const editing = ref<any>(null); const file = ref<File|null>(null); const form = reactive<any>({ title:'', description:'', question:'', answer:'', label:'', key:'', value:'', category:'Umum', image_url:'', progress_date:new Date().toISOString().slice(0,10), percentage:0, sort_order:0, is_active:true }); const title = computed(() => ({gallery:'Gallery',progress:'Progress pembangunan',faq:'FAQ',contact:'Kontak'}[props.type])); const description = computed(() => ({gallery:'Foto publik PoliLand.',progress:'Perkembangan pembangunan.',faq:'Pertanyaan yang sering ditanyakan.',contact:'Informasi kontak perusahaan.'}[props.type]));
async function load(){ loading.value=true; try { items.value = props.type==='gallery'?await galleryService.getGallery(false):props.type==='progress'?await progressService.getProgress(true):props.type==='faq'?await faqService.getFaqs():await contactService.getContacts() } catch(e){ emit('notify',e instanceof Error?e.message:'Gagal memuat data.','error') } finally{loading.value=false} }
function openNew(){ editing.value=null; Object.assign(form,{title:'',description:'',question:'',answer:'',label:'',key:'',value:'',category:'Umum',image_url:'',progress_date:new Date().toISOString().slice(0,10),percentage:0,sort_order:items.value.length,is_active:true}); file.value=null; open.value=true }
function edit(item:any){ editing.value=item; Object.assign(form,{...item,title:item.title||item.question||'',description:item.description||item.answer||item.value||'',key:item.key||'',label:item.label||''}); open.value=true }
function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}
async function save(){ saving.value=true; try { let payload:any={...form}; if(props.type==='faq') payload={question:form.title,answer:form.description,sort_order:form.sort_order,is_active:form.is_active}; if(props.type==='contact') payload={key:form.key,label:form.label,value:form.description}; if(props.type==='gallery'&&file.value){const u=await galleryService.uploadImage(file.value);payload.image_url=u.url} if(props.type==='progress'&&file.value) payload.image_url=await progressService.uploadImage(file.value); if(editing.value){ if(props.type==='gallery') await galleryService.updateGallery(editing.value.id,payload); else if(props.type==='progress') await progressService.updateProgress(editing.value.id,payload); else if(props.type==='faq') await faqService.updateFaq(editing.value.id,payload); else await contactService.updateContact(editing.value.id,payload.value) } else { if(props.type==='gallery') await galleryService.createGallery(payload); else if(props.type==='progress') await progressService.createProgress(payload); else if(props.type==='faq') await faqService.createFaq(payload); else await contactService.upsertContact(payload) } open.value=false; emit('notify','Data berhasil disimpan.'); await load() } catch(e){emit('notify',e instanceof Error?e.message:'Gagal menyimpan data.','error')} finally{saving.value=false} }
async function remove(item:any){if(!confirm('Hapus data ini?'))return; try{if(props.type==='gallery')await galleryService.deleteGallery(item.id,item.image_url);else if(props.type==='progress')await progressService.deleteProgress(item.id,item.image_url);else if(props.type==='faq')await faqService.deleteFaq(item.id);else return;emit('notify','Data berhasil dihapus.');await load()}catch(e){emit('notify',e instanceof Error?e.message:'Gagal menghapus data.','error')}} onMounted(load)
</script>
<style scoped>.panel{padding:18px;border:1px solid var(--border-default);border-radius:var(--radius-card);background:var(--surface-primary)}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.panel h2{margin:0;font-size:20px}.panel p{margin:5px 0 18px;color:var(--text-secondary);font-size:13px}.primary{min-height:44px;border:0;border-radius:var(--radius-control);padding:0 14px;background:var(--poliland-green);color:white;font:inherit;font-size:12px;font-weight:700}.items{display:grid;gap:8px}.item{display:flex;justify-content:space-between;gap:14px;padding:14px;border:1px solid var(--border-default);border-radius:var(--radius-control)}.item strong{font-size:14px}.item p{margin:4px 0;font-size:12px}.item small{color:var(--text-secondary)}.actions{display:flex;gap:6px;align-items:center}.actions button{min-height:44px;border:1px solid var(--border-default);border-radius:var(--radius-control);padding:0 10px;background:var(--surface-primary);font:inherit;font-size:12px}.danger{color:var(--status-danger)}.state{padding:40px;text-align:center;color:var(--text-secondary)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-grid label{display:grid;gap:6px;color:var(--text-secondary);font-size:12px;font-weight:700}.wide,.check{grid-column:1/-1}input,textarea{width:100%;box-sizing:border-box;border:1px solid var(--border-default);border-radius:var(--radius-control);padding:12px;background:var(--surface-primary);font:inherit}.check{display:flex!important;align-items:center;grid-template-columns:auto 1fr}.check input{width:auto}@media(max-width:620px){.panel-heading,.item{align-items:stretch;flex-direction:column}.form-grid{grid-template-columns:1fr}.wide,.check{grid-column:auto}}
</style>
